def shape(value):
    if value is None:
        return {"type": ["string", "null"]}
    if isinstance(value, bool):
        return {"type": "boolean"}
    if isinstance(value, int):
        return {"type": "integer"}
    if isinstance(value, float):
        return {"type": "number"}
    if isinstance(value, list):
        return {"type": "array", "items": shape(value[0]) if value else {}}
    if isinstance(value, dict):
        return {"type": "object", "properties": {k: shape(v) for k, v in value.items()}}
    return {"type": "string"}

def reply(example, description, status=200):
    return {str(status): {"description": description, "content": {"application/json": {"schema": shape(example), "example": example}}}}

def body(example, required=(), description="JSON request", media="application/json"):
    schema = shape(example)
    if required:
        schema["required"] = list(required)
    return {"required": bool(required), "description": description, "content": {media: {"schema": schema, "example": example}}}

def query(name, typ="string", description=""):
    return {"name": name, "in": "query", "required": False, "schema": {"type": typ}, "description": description}

